	var table = zenPage.getComponentById('deployments');
	var compNm = zenPage.getComponentById('comp').getValue();

    	zenPage.getComponentById('infoLbl').setValue(compNm);
    	zenPage.setSessionValues();
	table.executeQuery();


  set qt = $get(%session.Data("QueryType"))
  set compNm = $get(%session.Data("Component"))

  set sql=""
 if (qt = "C")
 {
	 set sql= "select  ci.ClassName, i.ImplementionDate,  ci.ClassExportFileVersion, ci.ClassExportFile,  c.ComponentName, i.ImplFile, ci.ClassExportFileInformation, i.ImplFileInformation, i.ImplFileVersion, n.NameSpace, e.Name "

 _ " from Component c,  Namespaces n, ComponentImpl i, Environment e,"
 _ " ClassItem ci "
 _ " where c.NameSpace = n.ID and c.ID = i.ComponentName and i.Environment = e.ID "
 _ " and i.ImplFile = ci.ClassExportFile and ci.importDate = i.ImplementionDate "
 }
 else
 {
 set sql="select c.ComponentName, e.Name, i.ImplementionDate, i.ImplFile, i.ImplFileVersion, i.ImplFileInformation, n.NameSpace"
  _ " from Component c,  Namespaces n, ComponentImpl i, Environment e " 
  _ " where c.NameSpace = n.ID and c.ID = i.ComponentName and i.Environment = e.ID"
 }
  if (compNm '= "")
 {
  set sql= sql _ " AND c.ComponentName = '" _compNm _ "'"
 }
 set sql= sql _ " ORDER BY i.ImplementionDate DESC"
  Set tRS = ##class(%ResultSet).%New()
    Set tSC = tRS.Prepare(sql)
    Set pInfo.queryText = sql

    Quit tRS
